// Hand-authored circuit, timing and functional drawings for the published question text.
// Everything is local SVG. Values are givens, never calculated answers.
const ink='currentColor', accent='var(--diagram-accent, #20b6a3)', muted='var(--diagram-muted, #788690)';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const path=(d,color=ink,dash='')=>`<path d="${d}" fill="none" stroke="${color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"${dash?` stroke-dasharray="${dash}"`:''}/>`;
const text=(x,y,s,anchor='middle',color=ink,size=15)=>`<text x="${x}" y="${y}" text-anchor="${anchor}" fill="${color}" font-size="${size}">${esc(s)}</text>`;
const dot=(x,y)=>`<circle cx="${x}" cy="${y}" r="3.5" fill="currentColor"/>`;
const ground=(x,y)=>path(`M${x} ${y}v9m-14 0h28m-23 6h18m-13 6h8`);
const arrow=(x,y,xx,yy,color=accent)=>{const a=Math.atan2(yy-y,xx-x),v=(r,t)=>`${xx-r*Math.cos(a+t)},${yy-r*Math.sin(a+t)}`;return path(`M${x} ${y}L${xx} ${yy}`,color)+`<path d="M${xx},${yy}L${v(9,.45)}L${v(9,-.45)}Z" fill="${color}"/>`;};
const resistor=(x,y,xx,yy,label,side=1)=>{const vertical=x===xx,mx=(x+xx)/2,my=(y+yy)/2;return vertical?path(`M${x} ${y}V${my-27}l-7 5 14 9-14 9 14 9-14 9 7 5V${yy}`)+text(x+side*20,my+5,label,side<0?'end':'start'):path(`M${x} ${y}H${mx-27}l5-7 9 14 9-14 9 14 9-14 5 7H${xx}`)+text(mx,y-17,label);};
const capacitor=(x,y,xx,yy,label,side=1)=>{const mx=(x+xx)/2,my=(y+yy)/2;return x===xx?path(`M${x} ${y}V${my-6}m-18 0h36m-36 12h36m-18 0V${yy}`)+text(x+side*27,my+5,label,side<0?'end':'start'):path(`M${x} ${y}H${mx-6}m0-18v36m12-36v36m0-18H${xx}`)+text(mx,y-27,label);};
const source=(x,y,voltage,ac=false)=>path(`M${x} ${y-55}V${y-24}m0 48v31`)+`<circle cx="${x}" cy="${y}" r="24" stroke="currentColor" stroke-width="2" fill="none"/>`+(ac?path(`M${x-16} ${y}q8-22 16 0t16 0`):text(x,y-3,'+')+text(x,y+16,'−'))+text(x-35,y+5,voltage,'end');
const current=(x,y,label,down=false,dependent=false)=>path(`M${x} ${y-55}V${y-27}m0 54v28`)+(dependent?path(`M${x} ${y-28}l24 28-24 28-24-28Z`):`<circle cx="${x}" cy="${y}" r="26" stroke="currentColor" stroke-width="2" fill="none"/>`)+arrow(x,y+(down?-14:14),x,y+(down?14:-14),ink)+text(x+36,y+5,label,'start');
const box=(x,y,w,h,lines)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="8" stroke="currentColor" stroke-width="2" fill="none"/>`+lines.map((l,i)=>text(x+w/2,y+h/2+(i-(lines.length-1)/2)*21+5,l)).join('');
const note=(s,y=333)=>text(360,y,s,'middle',muted,14);
// Terminal positions: base/gate (x-55,y), collector/drain (x+30,y-55), emitter/source (x+30,y+55).
const npn=(x,y,name='NPN')=>path(`M${x-55} ${y}H${x}m0-24v48m0-13 30 25V${y+55}M${x} ${y-11}l30-25V${y-55}`)+arrow(x+10,y+20,x+27,y+33,ink)+text(x+46,y,name,'start');
const mos=(x,y,name='NMOS',pmos=false)=>path(`M${x-55} ${y}H${x-9}m0-26v52m9-49v46m0-38h30V${y-55}M${x} ${y+15}h30V${y+55}`)+(pmos?`<circle cx="${x-15}" cy="${y}" r="5" stroke="currentColor" stroke-width="2" fill="var(--bg,white)"/>`:'')+text(x+45,y,name,'start');
const flow=(inputs,label,outputs,footer='')=>{const x=270,y=82,w=210,h=170;let b=box(x,y,w,h,label);inputs.forEach((s,i)=>{const yy=y+(i+1)*h/(inputs.length+1);b+=text(140,yy-10,s)+arrow(90,yy,x,yy);});outputs.forEach((s,i)=>{const yy=y+(i+1)*h/(outputs.length+1);b+=arrow(x+w,yy,630,yy)+text(592,yy-10,s);});return b+note(footer);};
const divider=({v,r1,r2,extra,kind='resistor',port='',foot=''})=>{let b=source(110,182,v)+path('M110 127V72')+resistor(110,72,350,72,r1)+resistor(350,72,350,275,r2,-1)+path('M110 237V275H350')+ground(260,275)+dot(350,72)+text(350,48,port||'A');if(extra){b+=path('M350 72H550M350 275H550');b+=kind==='current'?current(550,178,extra):kind==='dependent'?current(550,178,extra,false,true):kind==='short'?path('M550 72V275')+arrow(570,150,570,220)+text(583,184,'ISC = ?','start'):resistor(550,72,550,275,extra);if(kind==='current'||kind==='dependent')b+=path('M550 72V123M550 233V275');}return b+note(foot);};
const rc=({v,r,c,initial='',foot='',ac=false,highpass=false})=>source(125,183,v,ac)+path('M125 128V78')+(highpass?capacitor(125,78,430,78,c):resistor(125,78,430,78,r))+(highpass?resistor(430,78,430,278,r):capacitor(430,78,430,278,c))+path('M125 238V278H430')+ground(290,278)+dot(430,78)+path('M430 78H540')+text(550,82,'vOUT','start',accent)+text(450,230,initial,'start',muted,14)+note(foot);
const discharge=(r,c,initial,foot)=>resistor(225,80,225,270,r,-1)+capacitor(475,80,475,270,c)+path('M225 80H475M225 270H475')+text(445,125,'+')+text(445,230,'−')+text(350,49,initial)+note(foot);
const bjtStage=({rs='',rc:collector='',re='',load='',bias='',follower=false,rb=''})=>{let b=npn(335,174)+path('M180 174H280')+text(152,178,'vIN','end',accent);if(rs)b=resistor(110,174,280,174,rs)+text(80,178,'vS','end',accent)+npn(335,174);if(collector)b+=resistor(365,36,365,119,collector,-1)+ground(365,36);else b+=path('M365 119V58')+ground(365,58);if(re)b+=resistor(365,229,365,295,re,-1)+ground(365,295);else b+=path('M365 229V285')+ground(365,285);const yy=follower?229:119;b+=dot(365,yy)+path(`M365 ${yy}H550`)+text(585,yy+5,'vOUT','start',accent);if(load)b+=resistor(550,yy,550,285,load)+ground(550,285);if(rb)b+=dot(245,174)+resistor(245,174,245,285,rb,-1)+ground(245,285);return b+note(bias)+note('Small-signal view: supplies at AC ground; coupling capacitors shorted.',356);};
const transistorBias=({type='npn',top='',left='',bottom='Ground',foot=''})=>(type==='npn'?npn(345,180):mos(345,180,type==='pmos'?'PMOS':'NMOS',type==='pmos'))+path('M290 180H170M375 125V75M375 235V275')+text(155,184,left,'end')+text(375,52,top)+text(375,305,bottom)+note(foot,343);
const timing=(rows,footer)=>{const left=145,right=655,top=70,gap=73;let b='';rows.forEach(([label,d],i)=>{const yy=top+i*gap;b+=text(left-20,yy+19,label,'end')+path(`M${left} ${yy+36}H${right}`,muted,'3 6')+path(d.map(([x,y],j)=>`${j?'L':'M'}${left+x} ${yy+y}`).join(' '),accent);});return b+note(footer);};
const pair=({tail,collector,base1,base2,foot,output=''})=>{let b=npn(240,168,'Q1')+npn(490,168,'Q2')+path('M270 223V250H520V223')+dot(395,250)+path('M395 250V262')+current(395,317,tail,true)+ground(395,372)+text(185,167,base1,'end')+text(435,167,base2,'end');for(const x of [270,520])b+=collector?resistor(x,32,x,113,collector,-1)+text(x,17,'+5 V'):path(`M${x} 113V48`)+text(x,26,'+5 V');if(output)b+=text(360,415,output,'middle',accent);return b+note(foot,447);};
const mirror=({mosfet=false,ref,bias,load='',foot})=>{let b=(mosfet?mos(235,190,'M1'):npn(235,190,'Q1'))+(mosfet?mos(475,190,'M2'):npn(475,190,'Q2'));b+=path('M180 190V105H355V190H420M265 135V105M505 135V65')+dot(265,105)+current(265,50,ref,true)+path('M265 -5V-15')+ground(265,245)+ground(505,245);if(load)b+=resistor(505,-10,505,65,load,-1)+text(505,-26,bias);else b+=text(505,44,bias);return `<g transform="translate(0 65)">${b}</g>`+note(foot,356);};
const specs=[];
const add=(slug,desc,caption,body,height=380)=>specs.push({slug,desc,caption,body,height});

add('expansion-three-way-current-divider','An upward 9 mA current source and three resistors, 2, 3 and 6 kiloohms, connect node A to ground. The requested current flows downward in the 3 kiloohm branch.','All four branches connect the same two nodes.',current(115,175,'9 mA')+path('M115 120V65H570M115 230V275H570')+[ [265,'2 kΩ'],[420,'3 kΩ'],[570,'6 kΩ'] ].map(([x,r])=>resistor(x,65,x,275,r,-1)).join('')+ground(345,275)+text(345,42,'A')+arrow(446,120,446,208)+text(468,169,'I = ?','start',accent));
add('expansion-two-mesh-shared-resistor','Three vertical branches share node A and ground. Left: 2 kiloohms over a 10 volt source. Middle: 2 kiloohms. Right: 4 kiloohms over a 4 volt source.','The middle-branch reference points from A to ground.',path('M145 60H580M145 292H580')+resistor(145,60,145,147,'2 kΩ',-1)+source(145,202,'10 V')+path('M145 257V292')+resistor(580,60,580,147,'4 kΩ',-1)+source(580,202,'4 V')+path('M580 257V292')+resistor(360,60,360,292,'2 kΩ',-1)+ground(360,292)+text(360,37,'A')+arrow(390,123,390,219)+text(410,177,'iL − iR','start',accent));
add('expansion-thevenin-port-resistance','18 volt source feeds node A through 3 kiloohms. A has 6 kiloohms to ground and 2 kiloohms to unloaded port P.','P and ground form the open output port.',divider({v:'18 V',r1:'3 kΩ',r2:'6 kΩ'})+resistor(350,72,600,72,'2 kΩ')+dot(600,72)+text(620,77,'P','start',accent)+path('M350 275H600')+dot(600,275));
add('expansion-norton-short-circuit-current','9 volt source feeds port P through 3 kiloohms. P has a 6 kiloohm resistor and an ideal short to ground.','The short-circuit current is measured in the added wire.',divider({v:'9 V',r1:'3 kΩ',r2:'6 kΩ',extra:'short',kind:'short',port:'P'}));
add('expansion-maximum-load-power','20 volt source feeds A through 4 kiloohms, with fixed 6 kiloohms and variable RL from A to ground.','Only RL is varied. The 6 kΩ branch stays connected.',divider({v:'20 V',r1:'4 kΩ',r2:'6 kΩ',extra:'RL > 0'}));
add('expansion-dependent-source-node','12 volt source feeds A through 4 kiloohms. A has 6 kiloohms to ground and an upward dependent current source equal to 0.10 millisiemens times VA.','The diamond is a voltage-controlled current source.',divider({v:'12 V',r1:'4 kΩ',r2:'6 kΩ',extra:'0.10 mS · VA',kind:'dependent'}));
add('expansion-rc-polarity-reversal','For nonnegative time, a minus 3 volt source drives a 10 microfarad capacitor through 2 kiloohms. Capacitor initial voltage is plus 6 volts.','Circuit after switching; voltage polarity is measured above ground.',rc({v:'−3 V',r:'2 kΩ',c:'10 μF',initial:'vC(0⁻) = +6 V',foot:'Evaluate vC at t = 20 ms.'}));
add('expansion-rc-charging-threshold','After switching, a 5 volt source charges 4.7 microfarads through 10 kiloohms. An ideal observer trips at 4 volts; initial voltage is 1 volt.','The threshold observer draws no current.',rc({v:'5 V',r:'10 kΩ',c:'4.7 μF',initial:'vC(0⁻) = 1 V',foot:'First trip at vC = 4 V; find time after t = 0.'}));
add('expansion-rc-initial-reverse-current','A 3 volt source drives a 20 microfarad capacitor through 2.5 kiloohms. Initial capacitor voltage is 8 volts. Current reference is source to capacitor.','A reference arrow defines the sign; actual current may be negative.',rc({v:'3 V',r:'2.5 kΩ',c:'20 μF',initial:'vC(0⁻) = 8 V',foot:'Find the signed current at t = 0⁺.'})+arrow(255,42,340,42)+text(295,26,'iR = ?','middle',accent));
add('expansion-rc-energy-released','A 50 microfarad capacitor, initially 6 volts, discharges only through 10 kiloohms until it reaches 2 volts.','No supply remains connected during the discharge.',discharge('10 kΩ','50 μF','vC(0) = 6 V','Measure resistor energy until vC first reaches 2 V.'));
add('expansion-rc-lowpass-cutoff','A sinusoidal source drives 3.3 kiloohms in series and 22 nanofarads to ground. Output is across the capacitor.','The ideal output measurement does not load the RC network.',rc({v:'vIN',r:'3.3 kΩ',c:'22 nF',ac:true,foot:'Find the −3 dB cutoff relative to the DC gain.'}));
add('expansion-rc-charge-then-discharge','A capacitor has two exclusive connections: 5 volts through 1 kiloohm for 0 to 10 milliseconds, then ground through 2 kiloohms. The capacitor is 10 microfarads, initially uncharged.','Only one switch branch is connected at a time.',capacitor(480,170,480,290,'10 μF')+ground(480,290)+path('M480 170H390L347 120M290 95H335M290 235H335')+dot(335,95)+dot(335,235)+resistor(120,95,290,95,'1 kΩ')+text(98,100,'+5 V','end')+resistor(120,235,290,235,'2 kΩ')+ground(120,235)+text(235,59,'0 ≤ t < 10 ms')+text(235,280,'t ≥ 10 ms')+text(565,170,'vC','start',accent)+note('vC(0) = 0 V; find vC at 30 ms.'));

add('expansion-bjt-loaded-common-emitter','Small-signal common emitter stage. Source resistance is 2.5 kiloohms; collector has 4 kiloohm resistor and 4 kiloohm load to AC ground. Emitter is at AC ground.','The two collector resistances act in parallel in this signal view.',bjtStage({rs:'Rs = 2.5 kΩ',rc:'RC = 4 kΩ',load:'RL = 4 kΩ',bias:'IC = 1 mA; β = 100; VT = 25 mV; ro = ∞'}));
add('expansion-bjt-input-resistance-bias-network','Looking into the base, the 10 kiloohm bias resistance is in parallel with r pi. Emitter is at AC ground.','Only input paths are drawn; transistor capacitances are neglected.',path('M145 75H505M245 275H505')+resistor(245,75,245,275,'10 kΩ',-1)+resistor(505,75,505,275,'rπ')+ground(380,275)+text(140,54,'Base port')+arrow(95,75,190,75)+text(360,36,'RIN = ?','middle',accent)+note('IC = 1.5 mA; β = 120; VT = 25 mV; emitter at AC ground.'));
add('expansion-bjt-exact-early-resistance','NPN emitter is grounded, base-emitter voltage held at 0.70 volts and collector-emitter voltage biased at 2 volts. Output resistance uses the local collector-current slope.','Hold VBE fixed while perturbing the collector voltage.',transistorBias({top:'VCE = 2 V; IC = 1 mA',left:'VBE = 0.70 V',foot:'VA = 50 V; find the exact incremental output resistance.'}));
add('expansion-bjt-forced-beta-resistor','An NPN low-side switch has a 590 ohm collector load to 12 volts, emitter at ground, and base driven from 3.3 volts through unknown RB.','The requested RB is a design value, not an assumed transistor parameter.',npn(340,177)+resistor(370,30,370,122,'590 Ω',-1)+text(370,17,'+12 V')+resistor(110,177,285,177,'RB = ?')+text(95,182,'3.3 V','end')+ground(370,232)+note('VCE(sat) = 0.20 V; VBE(sat) = 0.80 V; require IC / IB ≤ 10.'));
add('expansion-bjt-follower-source-loading','Emitter follower signal view. Source drives base through 2.5 kiloohms. Collector is AC grounded, emitter has 1 kiloohm RE and 1 kiloohm load.','The DC supply is AC ground; the output is taken at the emitter.',bjtStage({rs:'Rs = 2.5 kΩ',re:'RE = 1 kΩ',load:'RL = 1 kΩ',follower:true,bias:'IC = 1 mA; β = 99; VT = 25 mV; ro = ∞'}));
add('expansion-bjt-unbypassed-emitter-gain','Common emitter signal view. An ideal input drives the base, collector has 5 kiloohm resistor and 5 kiloohm load; emitter has unbypassed 250 ohms.','The emitter resistor remains in the signal path.',bjtStage({rc:'RC = 5 kΩ',re:'RE = 250 Ω',load:'RL = 5 kΩ',bias:'IC = 1 mA; β = 100; VT = 25 mV; ro = ∞'}));
add('expansion-mos-transconductance-overdrive','NMOS source and body grounded. Gate at 1.1 volts, drain at 2 volts, threshold 0.6 volts and bias current 2 milliamperes.','The gate is varied infinitesimally while drain voltage stays fixed.',transistorBias({type:'mos',top:'VDS = 2 V; ID = 2 mA',left:'VGS = 1.1 V',bottom:'Source and body: 0 V',foot:'VTH = 0.6 V; λ = 0; gm = ?'}));
add('expansion-mos-channel-modulation-resistance','NMOS source and body grounded. Gate at 1.6 volts and drain at 5 volts. The drain current includes channel-length modulation.','Output resistance is a derivative at fixed gate voltage.',transistorBias({type:'mos',top:'VDS = 5 V',left:'VGS = 1.6 V',bottom:'Source and body: 0 V',foot:'VTH = 0.6 V; k = 2 mA/V²; λ = 0.04 V⁻¹; ro = ?'}));
add('expansion-mos-loaded-common-source-gain','Common-source small-signal model: gm vin current source, 100 kiloohm ro, 10 kiloohm RD and 10 kiloohm RL all connect drain output to AC ground.','Equivalent signal circuit; all four branches share the output node.',path('M140 75H565M140 270H565')+current(140,172,'',true,true)+text(140,299,'gm · vIN')+path('M140 75V117M140 227V270')+[[300,'ro = 100 kΩ'],[435,'RD = 10 kΩ'],[565,'RL = 10 kΩ']].map(([x,l])=>resistor(x,75,x,270,l,-1)).join('')+ground(365,270)+text(365,45,'vOUT','middle',accent)+note('gm = 4 mS; source and body at AC ground.'));
add('expansion-mos-follower-body-effect','NMOS source follower. Drain is at AC ground; gate is input. Source output has bias resistance 100 kiloohms and load 2 kiloohms to ground; transistor body is grounded.','The transistor model includes gm, gmb and finite ro.',mos(320,125)+path('M350 70V38M350 180H525')+ground(350,38)+text(220,130,'vIN','end',accent)+resistor(350,180,350,290,'rbias = 100 kΩ',-1)+resistor(525,180,525,290,'RL = 2 kΩ')+ground(350,290)+ground(525,290)+text(568,182,'vOUT','start',accent)+note('gm = 5 mS; gmb = 1 mS; ro = 100 kΩ; body at ground.'));
add('expansion-pmos-moving-drain-regions','PMOS source and body at 5 volts, gate at 2.5 volts. Drain is first 2 volts then 4 volts.','For PMOS, use VSG and VSD with the source at the upper terminal.',mos(345,180,'PMOS',true)+path('M375 125V75M375 235V275M290 180H180')+text(375,53,'Source / body = +5 V')+text(375,302,'Drain: +2.0 V → +4.0 V')+text(165,184,'Gate = +2.5 V','end')+note('VTP = −0.7 V; classify each operating point.'));
add('expansion-mos-miller-plateau-time','Driver modeled as 10 volts through 2 ohms and external 8 ohms to NMOS gate. Source grounded. Gate remains at the 4 volt plateau while 12 nanocoulombs are delivered.','Only the specified gate-to-drain charge interval is included.',mos(500,175)+resistor(105,175,265,175,'Driver: 2 Ω')+resistor(265,175,445,175,'External: 8 Ω')+text(95,179,'10 V','end')+ground(530,230)+text(530,99,'Drain falling')+text(350,228,'Gate plateau = 4 V')+arrow(230,120,350,120)+text(290,98,'Gate current','middle',accent)+note('QGD = 12 nC during this interval; find plateau time.'));

add('expansion-counter-width','A binary counter register stores states 0 through 999 and next-state logic returns 999 to zero. Register width is unknown.','State labels describe the required range, not the storage width.',flow(['Clock'],['Binary count register','Width = ?'],['Count 0…999'],'After 999, the next count is 0.'));
add('expansion-hold-buffer-skew','Launch register feeds combinational logic then an optional delay then capture register. Launch clock-to-Q minimum is 0.08 ns, logic minimum 0.04 ns. Capture clock arrives 0.05 ns late and hold time is 0.12 ns.','The added delay is in the data path.',box(40,120,125,90,['Launch FF','tCQ,min 0.08 ns'])+arrow(165,165,225,165)+box(225,120,125,90,['Logic','tmin 0.04 ns'])+arrow(350,165,405,165)+box(405,120,115,90,['Delay','Δ = ?'])+arrow(520,165,565,165)+box(565,120,125,90,['Capture FF','thold 0.12 ns'])+text(100,253,'Clock: t = 0')+text(620,253,'Clock: t = 0.05 ns')+note('All delays shown are minimum delays; ignore jitter.'));
add('expansion-pipeline-throughput','Four registered pipeline logic stages have delays 2.4, 1.6, 2.0 and 1.2 nanoseconds. Each has 0.6 nanoseconds total clock-to-Q and setup overhead.','One independent sample enters per cycle once the pipeline is full.',[2.4,1.6,2,1.2].map((d,i)=>box(30+i*174,115,138,100,[`Stage ${i+1}`,`${d.toFixed(1)} ns logic`])+(i<3?arrow(168+i*174,165,204+i*174,165):'')).join('')+note('Each register-to-register stage also needs 0.6 ns for tCQ + tsetup.'));
add('expansion-binary-gray-conversion','Five-bit binary input 10110 enters a reflected binary Gray converter. Five output bits are unknown.','Most significant bits are on the left.',flow(['10110'],['Binary → reflected','Gray conversion'],['g4 g3 g2 g1 g0'],'The prompt defines how adjacent binary bits are combined.'));
add('expansion-mux-shannon-decomposition','A two-input multiplexer selects D0 when b is zero and D1 when b is one. D0 and D1 are expressions of a and c to determine.','The select input is b; derive the data expressions from the function.',path('M295 70L445 110V260L295 300Z')+path('M170 125H295M170 245H295M445 185H610M370 300V280')+text(157,130,'D0 = ?','end',accent)+text(157,250,'D1 = ?','end',accent)+text(470,170,'F','start')+text(370,325,'Select: b')+text(317,133,'0')+text(317,253,'1')+note('F = (a AND b) OR ((NOT a) AND c)',358));
add('expansion-unsigned-adder-carry','An eight-bit unsigned adder takes 200 and 100. It exposes an eight-bit stored sum and a separate one-bit carry.','Carry is kept separate from the low eight sum bits.',flow(['A = 200','B = 100'],['8-bit unsigned','adder'],['8-bit sum = ?','Carry-out = ?']));
add('expansion-hdl-full-adder-carry','A full-adder functional block takes a, b and cin. The required output y is carry-out; the sum bit is unused.','Implement only the carry output.',flow(['a','b','cin'],['Full adder'],['Carry y','Sum unused'],'Inputs and output y are one bit.'));
add('expansion-hdl-two-bit-equality','Two words A with bits a1 a0 and B with bits b1 b0 enter an equality comparator, producing one-bit y.','The checker accepts individual bit names.',flow(['A: a1 a0','B: b1 b0'],['Unsigned two-bit','equality comparator'],['Equal: y']));
add('expansion-hdl-even-parity-bit','Payload bits a, b and c enter an even-parity generator. Parity bit y joins the transmitted four-bit packet.','The entire transmitted packet must have even parity.',flow(['a','b','c'],['Even-parity','bit generator'],['Parity y'],'Transmit [a b c y]; require an even number of ones.'));
add('expansion-hdl-priority-encoder-lsb','Requests r3 through r0 enter a priority encoder, r3 highest. Its output is a two-bit index; only the low bit y must be implemented.','No active request produces index 00.',flow(['r3 (highest)','r2','r1','r0 (lowest)'],['Priority encoder'],['Index MSB unused','Index LSB: y']));
