add('expansion-v3-difference-amplifier','Difference amplifier: 0.5 volt input through 10 kiloohms into minus input with 100 kiloohm feedback. 0.8 volt input through 10 kiloohms to plus input and 100 kiloohms from plus input to ground.','Resistor ratios match; the output is unloaded.',path('M420 130L420 260L535 195Z')+text(440,161,'−')+text(440,239,'+')+resistor(115,155,330,155,'R1 = 10 kΩ')+text(100,160,'0.5 V','end')+path('M330 155H420M330 155V50M600 50V195H535')+resistor(330,50,600,50,'R2 = 100 kΩ')+resistor(115,235,330,235,'R3 = 10 kΩ')+text(100,240,'0.8 V','end')+path('M330 235H420')+resistor(330,235,330,330,'R4 = 100 kΩ',-1)+ground(330,330)+dot(330,155)+dot(330,235)+text(620,200,'vOUT','start',accent)+note('Ideal op amp; ±12 V supplies; linear negative feedback.',382),405);
